var a=[{title:`Miért alakul ki`,text:`A DOMS általában ismeretlen mozdulatokat és ismételt excentrikus összehúzódásokat követ, amikor az izom megnyúlás közben fejt ki erőt. Az izomban és a környező szövetben több folyamat is szerepet játszik. A visszamaradt tejsav nem az oka. Az, hogy mennyire fáj, nem méri az edzés jóságát.`},{title:`Hogyan jön és megy`,text:`Az izomláz az edzés után néhány órával kezdődhet, a következő egy-három napban erősödhet, majd elmúlik. Egy ismerős gyakorlat gyakran kevesebb izomlázat okoz ugyanannyi mennyiségnél, ezt ismételt terhelési hatásnak hívják. Az erő építéséhez nincs szükség erős vagy tartós izomlázra.`},{title:`Edzés izomlázzal`,text:`Az enyhe, szétterjedő izomláz általában még lehetővé teszi a sétát, a mozgékonysági munkát vagy a könnyebb edzést, amíg jól mozogsz. Ha az izomláz korlátozza a hétköznapi mozgást, vagy megváltoztatja az emelési technikádat, csökkentsd az intenzitást, vagy vegyél több regenerációt. Egy ismeretlen, nagy mennyiségű edzés azonnali megismétlése ritkán jó módja a fejlődésnek. Az ismerős gyakorlatokat fokozatosan nehezítsd, és ne számíts arra, hogy a nyújtás vagy a levezetés megelőzi a másnapi izomlázat.`},{title:`Mikor kérj segítséget`,text:`Az egy ponton jelentkező éles fájdalom, a sok duzzanat, az egyértelmű gyengeség, a sötét vizelet, a láz vagy az enyhülés helyett romló tünetek nem normális DOMS. A súlyos jelek, főleg a sötét vizelet izomfájdalommal vagy gyengeséggel, azonnali orvosi vizsgálatot igényelnek.`},{title:`A TrainUp használata`,text:`Edzés után jelezheted a fájdalmat vagy kellemetlenséget, a testtáj és a gyakorlat megadásával. Bármilyen friss fájdalom esetén a terv nem lesz nehezebb, amikor újragenerálod. Ha egy gyakorlat edzés közben fáj, koppints a „Fájdalmat érzek” gombra, hogy azonnal véget érjen; addig nem kerül a terveidbe, amíg a Profilban vissza nem kapcsolod.`}];var s=[{label:`NHS: késleltetett izomláz`,url:`https://www.leicspart.nhs.uk/msk-physiotherapy-resources-getting-started/msk-physiotherapy-resources-faqs/`},{label:`Kutatási áttekintés: késleltetett izomláz`,url:`https://pmc.ncbi.nlm.nih.gov/articles/PMC13627368/`},{label:`2026-os ACSM állásfoglalás`,url:`https://pubmed.ncbi.nlm.nih.gov/41843416/`}];var l={sections:a,sources:s};export{l as default,a as sections,s as sources};